CREATE TRIGGER RefStlFieldMapping_Version_Create
	ON RefStlFieldMapping
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT SFM_PK, 'SFM'
	FROM inserted
GO
CREATE TRIGGER RefStlFieldMapping_Version_Update
	ON RefStlFieldMapping
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON SFM_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
CREATE TRIGGER RefStlFieldMapping_DataChangeHistory
	ON RefStlFieldMapping
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT SFM_PK, 'SFM' FROM inserted
	UNION
	SELECT SFM_PK, 'SFM' FROM deleted

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO
CREATE TRIGGER RefStlFieldMapping_DataProcessingResult_Delete
	ON RefStlFieldMapping
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.SFM_PK
	END
